/// The checkpoint is driven by hand with a collection forced before every
/// job: saved strings, records, arrays and awaited promises survive while
/// their frames sit in the queue. Node 24 prints the same two lines.
#[test]
fn awaited_values_survive_a_collection_forced_before_every_job() {
    use varta_compiler::suspension_test_hook as hook;
    let source = r##"
async function keep(label: string): Promise<string> {
  const item = { name: label + "!", tags: [label + "/a", label + "/b"] };
  await null;
  const junk = "x".repeat(64);
  const tail = await Promise.resolve(label + "?");
  return item.name + item.tags[1] + tail + String(junk.length);
}
export async function main(): Promise<void> {
  const a = keep("a");
  const b = keep("b").then((s) => s + "#");
  const first = await a;
  console.log(first);
  const second = await b;
  console.log(second);
}
"##;
    let bytes = hook::compile_with_profile(
        source,
        varta_common::language::LanguageProfile::CheckedF64Utf16V34,
    )
    .unwrap();
    let runtime = crate::VartaRuntime::new();
    let module = runtime.prepare_module(&bytes).unwrap();
    let mut execution = crate::execution::Execution::new(&runtime.engine, &[], None).unwrap();
    let instance = execution.instantiate_prepared(&module).unwrap();
    let store = &mut execution.store;
    let start = instance.get_func(&mut *store, "_start").unwrap();
    start.call(&mut *store, &[], &mut []).unwrap();
    let collect = instance
        .get_typed_func::<(), ()>(&mut *store, hook::COLLECT)
        .unwrap();
    let resume = instance
        .get_typed_func::<(i64, i32, i64), i32>(
            &mut *store,
            varta_common::function::frame::RESUME_EXPORT,
        )
        .unwrap();
    let mut jobs = 0;
    while let Some(token) = store.data_mut().scheduler.next().unwrap() {
        collect.call(&mut *store, ()).unwrap();
        resume.call(&mut *store, (token, 0, 0)).unwrap();
        jobs += 1;
    }
    assert!(jobs > 4, "{jobs}");
    assert!(store.data().scheduler.unhandled_rejection().is_none());
    assert_eq!(
        store.data().output.lines,
        ["varta log: a!a/ba?64", "varta log: b!b/bb?64#"]
    );
}
#[test]
fn suspended_frames_keep_their_values_across_forced_collections() {
    run(
        include_str!("promise_cases/lifetime.ts"),
        &["a-3:a-3/b:true b-4:b-4/b:true", "finished 8", "depth 10"],
    );
}
